const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(url,label)=>/^https?:\/\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);
const options=(xs,value)=>xs.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
const state={scope:'core',year:'all',stage:'all',queue:'all',q:'',page:1};
const labels={conflict:'Resolve count / identity discrepancy',eligibility:'Verify doctorate',independent_denominator:'Find independent full roster',research_classification:'Classify remaining people',initial_destination:'Trace initial outcome',independent_dates:'Verify independent dates',complete:'Defined population resolved'};
export function checklistRows(data,f={}){return (data?.rows||[]).filter(r=>(!f.scope||f.scope==='all'||f.scope==='priority'&&r.priority||f.scope===r.scope)&&(!f.year||f.year==='all'||String(r.year)===f.year)&&(!f.stage||f.stage==='all'||r.next_stage===f.stage)&&(!f.queue||f.queue==='all'||f.queue==='first_pass'&&!r.work_complete&&!r.annual_reviews.length||f.queue==='revisit'&&!r.work_complete&&r.annual_reviews.length||f.queue==='resolved'&&r.work_complete)&&(!f.q||r.school.toLowerCase().includes(f.q.toLowerCase())));}
function body(data){
  const rows=checklistRows(data,state),pages=Math.max(1,Math.ceil(rows.length/20));state.page=Math.min(pages,Math.max(1,Number(state.page)||1));
  return `<p role="status" class="coverage-count">${rows.length} matching school-year cells · page ${state.page} of ${pages}. Blank evidence stays open; a row with no people collected is not a zero-graduate cohort.</p><div class="table-scroll"><table class="audit-table"><thead><tr><th>Program / source year</th><th>1–2 · Population & independent count</th><th>3 · Named roster</th><th>4 · Research labels</th><th>5 · Initial destination</th><th>6 · Independent dates</th><th>Next action & evidence</th></tr></thead><tbody>${rows.slice((state.page-1)*20,state.page*20).map(r=>{
    const n=r.recorded_count,fields=r.label_counts;
    const review=(r.annual_reviews||[]).map(a=>`<li><strong>${esc(a.checked_at)} · ${esc(a.result||a.access||'Reviewed')}</strong><p>${esc(a.finding)}</p>${a.query?`<p>Search: <code>${esc(a.query)}</code></p>`:''}${a.next_step?`<p>Next: ${esc(a.next_step)}</p>`:''}${(a.sources||[]).map(s=>`${link(s.url,s.label||'Official / primary source')}${s.pages?.length?' · page '+esc(s.pages.join(', ')):''}`).join('<br>')}</li>`).join('');
    return `<tr><td><strong>${esc(r.school)}</strong><span class="cell-note">${r.year} · ${r.kind==='economics'?'Economics / IO subset':'Marketing · all fields'} · ${r.scope}${r.priority?' · priority':''}</span></td><td>${r.cohort_complete?'✓ Defined population matched':'○ Independent denominator open'}<span class="cell-note">Independent count: ${r.independent_count??'?'}${r.population?' · '+esc(({degree_completion_window:'Completion window',school_announced_graduating_class:'Announced graduating class',published_degree_conferment_class:'Published conferment class'})[r.population.kind]||'Defined population'):''}</span></td><td>${r.source_matched?'✓ Source list matched':n?'◐ Partial collection':'○ Not collected'}<span class="cell-note">${n} collected / ${r.source_listed_count??'?'} in source list</span></td><td>${n?`Q ${fields.qm} · CB ${fields.cb} · Strategy ${fields.strategy}<span class="cell-note">${fields.unclassified} unclassified / ${n} recorded; labels may overlap</span>`:'Unknown; no named roster'}</td><td>${n?`${n-r.unknown_destination_ids.length} / ${n} recorded`:'Unknown'}<span class="cell-note">${r.unknown_destination_ids.length?'Unknown outcomes remain in the population':''}</span></td><td>${n?`First-job year: ${n-r.missing_first_job_year_ids.length} / ${n}<span class="cell-note">Graduation year: ${n-r.missing_graduation_year_ids.length} / ${n}</span>`:'Unknown'}</td><td><strong>${esc(labels[r.next_stage]||r.next_stage)}</strong><button type="button" class="text-button" data-audit-program="${esc(r.program_id)}" data-audit-period="${r.year}">Review roster & people</button><details><summary>${r.work_complete?'Resolved':r.annual_reviews.length?'Reviewed · evidence gap':'First pass pending'} · ${r.annual_reviews.length} dated source reviews</summary><p>${esc(r.next_action)}</p>${review?`<ul class="source-list">${review}</ul>`:'<p>No edition-specific review is logged here. Existing roster evidence is available in the roster dialog.</p>'}${r.issues.map(i=>`<p><strong>Open issue:</strong> ${esc(i.detail)}</p>`).join('')}</details></td></tr>`;
  }).join('')}</tbody></table></div><div class="filter-bottom"><button type="button" class="button secondary" data-ck-page="${state.page-1}" ${state.page<=1?'disabled':''}>Previous 20</button><button type="button" class="button secondary" data-ck-page="${state.page+1}" ${state.page>=pages?'disabled':''}>Next 20</button></div>`;
}
export function checklistMarkup(catalog){
  const data=catalog.cohort_checklist;if(!data)return '';
  const params=new URLSearchParams(globalThis.location?.hash?.split('?')[1]||'');for(const [k,v]of Object.entries({scope:'core',year:'all',stage:'all',queue:'all',q:'',page:1}))state[k]=params.get('ck_'+k)||v;
  const s=data.summary;
  return `<section class="panel" id="cohort-checklist"><div class="panel-heading"><div><p class="eyebrow">FIXED SCOPE · SIX CHECKS PER CELL</p><h2>Systematic cohort checklist</h2></div><a class="button secondary" href="data/cohort-checklist.csv" download>Download all ${s.total_cells} cells · CSV</a></div><div class="prose"><p><strong>${s.core_programs} target Marketing schools × ${data.history_years[0]}–${data.history_years.at(-1)} = ${s.core_cells} core cells.</strong> ${s.extension_programs} separate extension programs add ${s.extension_cells} cells. The fourteen priority programs are a work order inside this fixed universe. The ${data.current_cycle_separate.replace('-','–')} candidate season stays in the separate current-market section.</p><p>For each school and year: define the population → establish an independent denominator → match every name → classify Quant / CB / Strategy → trace initial destinations → verify graduation and first-job dates independently. Industry, CB, Strategy and unknown outcomes remain included. Reported labels do not automatically prove a complete research-field subset.</p><p><strong>${s.defined_rosters_complete} defined rosters complete; ${s.fully_resolved_cells} cells have every displayed gap resolved.</strong> These are different milestones. ${s.first_pass_remaining} cells have no detailed annual-source review in this checklist yet; ${s.revisit_with_evidence_gap} reviewed cells stay in a separate evidence-gap revisit queue. ${s.without_recorded_people} cells have no collected names and remain open. Search attempts and tentative ceremony lists are recorded below; they do not establish awarded-degree completeness.</p></div><form id="checklist-filters" class="coverage-filters"><label class="filter-label">Review scope<select name="scope">${options([['priority','14 priority programs'],['core','58 target Marketing schools'],['extension','Separate extensions'],['all',`All ${s.total_cells} school-year cells`]],state.scope)}</select></label><label class="filter-label">Source year<select name="year">${options([['all','All four years'],...data.history_years.map(y=>[String(y),String(y)])],state.year)}</select></label><label class="filter-label">Next unresolved step<select name="stage">${options([['all','All stages'],...Object.entries(labels)],state.stage)}</select></label><label class="filter-label">Research queue<select name="queue">${options([['all','All research states'],['first_pass','No annual review yet'],['revisit','Reviewed · evidence gap'],['resolved','All six checks resolved']],state.queue)}</select></label><label class="filter-label">Find a school<input type="search" name="q" value="${esc(state.q)}" placeholder="e.g. Berkeley, Wisconsin"></label></form><div id="checklist-results">${body(data)}</div><p class="chart-note">✓ is a source-list match or defined-population match, as labelled; it never converts an unknown annual cohort into zero. The deterministic next-action queue is included in the <a href="data/cohort-checklist.json" download>JSON export</a>.</p></section>`;
}
export function bindChecklist(catalog,rebindCells){
  const form=document.querySelector('#checklist-filters'),results=document.querySelector('#checklist-results');if(!form||!results)return;
  function redraw(){const params=new URLSearchParams(location.hash.split('?')[1]||'');for(const [k,v]of Object.entries(state))params.set('ck_'+k,v);history.replaceState(null,'','#coverage?'+params);results.innerHTML=body(catalog.cohort_checklist);results.querySelectorAll('[data-ck-page]').forEach(b=>b.onclick=()=>{state.page=Number(b.dataset.ckPage);redraw()});rebindCells();}
  form.onsubmit=e=>e.preventDefault();form.oninput=e=>{state[e.target.name]=e.target.value;state.page=1;redraw()};
  results.querySelectorAll('[data-ck-page]').forEach(b=>b.onclick=()=>{state.page=Number(b.dataset.ckPage);redraw()});
}
